/// Compute the convex hull of a set of integer points.
/// Return the hull's corner points in counter-clockwise order, starting from the
/// smallest point (smallest x, ties broken by smallest y). Points that lie on a
/// hull edge but are not corners are left out, and duplicate points count once.
///
/// Degenerate cases: no points give an empty vector; if all points are equal, return
/// that single point; if all points lie on one line, return its two endpoints,
/// smallest first. Return an empty vector if any coordinate has absolute value greater
/// than 1_000_000_000.
/// >>> convex_hull(vec![(0, 0), (4, 0), (4, 4), (0, 4), (2, 2)])
/// vec![(0, 0), (4, 0), (4, 4), (0, 4)]
/// >>> convex_hull(vec![(1, 1), (3, 3), (2, 2)])
/// vec![(1, 1), (3, 3)]
fn convex_hull(points: Vec<(i64, i64)>) -> Vec<(i64, i64)> {
    let limit = 1_000_000_000;
    if points.iter().any(|&(x, y)| x.abs() > limit || y.abs() > limit) {
        return vec![];
    }
    let mut pts = points.clone();
    pts.sort();
    pts.dedup();
    if pts.len() <= 2 {
        return pts;
    }
    let lower = chain(pts.iter().copied());
    let upper = chain(pts.iter().rev().copied());
    let mut hull = lower[..lower.len() - 1].to_vec();
    hull.extend_from_slice(&upper[..upper.len() - 1]);
    hull
}

fn cross(o: (i64, i64), a: (i64, i64), b: (i64, i64)) -> i64 {
    (a.0 - o.0) * (b.1 - o.1) - (a.1 - o.1) * (b.0 - o.0)
}

// One half of Andrew's monotone chain; drops collinear points.
fn chain(seq: impl Iterator<Item = (i64, i64)>) -> Vec<(i64, i64)> {
    let mut out: Vec<(i64, i64)> = Vec::new();
    for p in seq {
        while out.len() >= 2 && cross(out[out.len() - 2], out[out.len() - 1], p) <= 0 {
            out.pop();
        }
        out.push(p);
    }
    out
}
